// Phase 3: Constrained generation with heavy EOS penalty for first minExprTokens
// tokens to prevent premature single-variable span closure.
// validTokenGroups (variable names) are boosted to steer away from numeric literals.
var minExprTokens: nat := 25;
var exprSteps: nat := 0;

while steps < maxSteps && insideConstrainedOut && exprSteps < minExprTokens
  invariant 0 <= steps <= maxSteps
  invariant 0 <= exprSteps <= minExprTokens
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps, minExprTokens - exprSteps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.AdaptiveConstrainedStepWithPenalties(
    lm, parser, constrainedPrompt, currentConstrainedOut,
    validTokenGroups, 6.0, [eosToken], 8.0, 12, eosToken
  );
  steps := steps + 1;
  exprSteps := exprSteps + 1;
  if next == eosToken {
    // Even with 8.0 EOS penalty, model wants to stop.
    // Roll back to the last complete parse and close the span.
    var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
    generated := rg;
    currentConstrainedOut := rc;
    if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    }
    break;
  }
  var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
  generated := ag;
  insideConstrainedOut := ai;
  currentConstrainedOut := ac;
}

// Phase 4: Continue constrained generation with natural EOS (no penalty),
// tracking the longest complete parse. On EOS, rollback to complete and close.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.AdaptiveConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
  );
  steps := steps + 1;
  if next == eosToken {
    var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
    generated := rg;
    currentConstrainedOut := rc;
    if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    }
    break;
  }
  var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
  generated := ag;
  insideConstrainedOut := ai;
  currentConstrainedOut := ac;
}

// Emergency close: if span is still open after all phases, roll back to the
// last complete prefix and emit >> before returning.
if insideConstrainedOut && steps < maxSteps {
  var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
  generated := rg;
  currentConstrainedOut := rc;
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  }
}

